CREATE TRIGGER identity_users_insert BEFORE INSERT ON users
WHEN NEW.role <> 'admin' AND (EXISTS (SELECT 1 FROM admin_github_access WHERE lower(trim(protected_email))=lower(trim(NEW.email))) OR EXISTS (SELECT 1 FROM admin_github_identities WHERE lower(trim(github_email))=lower(trim(NEW.email))))
BEGIN SELECT RAISE(ABORT, 'admin_email_reserved'); END;

