INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('media-review','account',NULL,'0','Fotos y videos','Fotos pendientes y aprobación de medios','["aprobar fotos","aceptar fotos","foto pendiente","video pendiente","foto no publicada"]','Solo la administración aprueba los archivos del anuncio. Como dueño puedes revisarlos y retirarlos, pero no aprobarlos por tu cuenta.','["Abre Fotos y videos y consulta el estado de cada archivo.","Una foto o video nuevo queda pendiente hasta su revisión; no deshabilita por sí solo un anuncio ya aprobado.","Si fue rechazado o necesitas corregirlo, revisa el aviso y prepara un archivo válido.","No hay un plazo automático garantizado. Para consultar tu caso utiliza el WhatsApp de soporte."]','/mi-cuenta#mis-anuncios','Revisar estado de los medios','media') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('photo-edit','account',NULL,'0','Fotos y videos','Cambiar o agregar una foto','["cambiar foto","reemplazar foto","subir fotos","foto principal","foto de perfil","editar imagen"]','Las fotos se gestionan dentro de Editar anuncio, al inicio de la página.','["Elige tu anuncio y entra en Editar anuncio → Fotos y videos.","Para la imagen principal utiliza Elegir foto de perfil. Para la galería utiliza Elegir archivos.","Revisa el recorte y los efectos elegidos antes de enviarla. Cada foto final admite hasta 10 MB.","Envía la foto a revisión. Una foto nueva queda pendiente por separado; agregarla o eliminarla no retira por sí solo un anuncio aprobado."]','/mi-cuenta#mis-anuncios','Abrir fotos y videos','media') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('upload-error','account',NULL,'0','Fotos y videos','Una foto o video no se puede subir','["no puedo subir","no me deja subir","error al subir","png","heic","icloud","payload too large","archivo no compatible"]','Revisa el mensaje exacto junto al archivo: puede indicar tamaño, formato, duración, conexión o preparación incompleta.','["Descarga el original desde Fotos/Galería o iCloud y vuelve a seleccionarlo; una miniatura vacía no se puede subir.","Fotos: original de hasta 20 MB, convertido a un archivo final de hasta 10 MB. HEIC/HEIF depende de que el navegador pueda abrirlo.","Videos: original de hasta 50 MB, máximo 15 segundos y archivo final de hasta 12 MB. Si el códec no es compatible, exporta como MP4/H.264.","Mantén la pestaña abierta durante la preparación. Antes de repetir una carga comprueba si el archivo ya apareció; para soporte, conserva el texto del error y su código, sin enviar documentos privados por este chat."]','/mi-cuenta#mis-anuncios','Revisar mis archivos','media') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('video','account',NULL,'0','Fotos y videos','Subir un video al anuncio','["subir video","duracion","15 segundos","12 mb","mov","marca de agua video"]','Los videos se preparan y revisan antes de enviarlos; solo se guarda su versión final.','["En Fotos y videos → Elegir archivos, selecciona el video. Se admiten MP4, WebM y MOV compatibles.","Revisa el clip y su sonido, y activa la marca de agua si la deseas.","Usa Preparar video y revisar. El resultado debe durar hasta 15 segundos y pesar hasta 12 MB.","Envía los archivos a revisión. La galería admite hasta 3 videos; su reproducción empieza en 00:00."]','/mi-cuenta#mis-anuncios','Abrir videos del anuncio','media') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('photo-effects','account',NULL,'0','Fotos y videos','Marca de agua, recorte y difuminado','["difuminar","rostros","recortar","marca de agua","todas las fotos"]','Puedes revisar los efectos por archivo antes de subirlo. El difuminado facial está disponible para fotos, no videos.','["Selecciona las fotos en la galería o como foto principal.","Usa Opciones para todas las fotos seleccionadas para aplicar o quitar marca de agua y difuminado globalmente; después puedes ajustar cada una.","Abre cada foto para revisar su recorte y el resultado. La disponibilidad del difuminado depende de la configuración del sitio.","Los videos tienen marca de agua individual. Los cambios de efectos no modifican automáticamente archivos que ya subiste."]','/mi-cuenta#mis-anuncios','Abrir opciones de fotos','media') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('create','account',NULL,'0','Anuncios','Crear un anuncio','["crear anuncio","publicar anuncio","nuevo anuncio","registrar anuncio"]','Puedes guardar un borrador o enviar un anuncio a revisión; no se publica inmediatamente.','["Pulsa Crear anuncio y elige Escort, Agencia o Arriendo.","Completa nombre, ubicación, descripciones y contacto. Para Escort, género y edad adulta son obligatorios al enviar a revisión.","VIP está seleccionado inicialmente para un Escort nuevo. Usuario del anuncio, referencias y etiquetas siguen siendo opcionales; el resto está en Características opcionales.","Guarda y envía a revisión. Después podrás cargar medios y, en Escort, documentos privados. La administración debe aprobar la publicación."]','/mi-cuenta/nuevo-perfil','Crear anuncio',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('edit','account',NULL,'0','Anuncios','Editar los datos de mi anuncio','["editar anuncio","cambiar nombre","cambiar whatsapp","cambiar descripcion","editar perfil","modificar anuncio"]','Solo puedes editar anuncios que pertenecen a tu cuenta.','["En Mis anuncios elige Editar anuncio. También aparece Editar anuncio al abrir tu propio perfil.","Modifica los campos y utiliza Guardar cambios del anuncio.","Cambios relevantes pueden devolver el anuncio a revisión. Si únicamente cambias contactos en un anuncio aprobado, conserva su aprobación.","Las fotos, videos y documentos se guardan desde sus secciones; no necesitas volver a enviar todo el formulario para subirlos."]','/mi-cuenta#mis-anuncios','Editar mi anuncio','edit') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('preview','account',NULL,'0','Anuncios','Previsualizar un anuncio pendiente','["previsualizar","vista previa","ver borrador","ver anuncio pendiente","anuncio no publicado"]','Un anuncio no publicado tiene una vista previa privada para su dueño y administración.','["En Mis anuncios pulsa Previsualizar anuncio, o utiliza el botón del editor.","La vista previa puede mostrar medios pendientes, pero no hace público el anuncio.","Otras cuentas no tienen acceso y la vista previa no se indexa en Google.","El anuncio aparecerá públicamente únicamente cuando cumpla el estado y las condiciones de publicación."]','/mi-cuenta#mis-anuncios','Ver vista previa','preview') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('hide','account',NULL,'0','Anuncios','Ocultar o volver a mostrar mi anuncio','["ocultar mi anuncio","volver a mostrar","desactivar anuncio","pausar anuncio"]','Ocultar es reversible y no borra el anuncio, sus medios ni su revisión.','["En Mis anuncios o Editar anuncio busca Ocultar anuncio.","Confirma la acción del formulario para retirarlo del directorio.","Para recuperarlo utiliza Volver a mostrar. Su visibilidad también depende de su estado administrativo.","Ocultar no equivale a eliminar ni a cambiar su período de publicación."]','/mi-cuenta#mis-anuncios','Administrar visibilidad','edit') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('delete-ad','account',NULL,'0','Anuncios','Eliminar un anuncio','["eliminar anuncio","borrar anuncio","papelera","recuperar anuncio eliminado"]','El anuncio pasa a la papelera administrativa y deja de estar disponible en tu panel; solo administración puede restaurarlo.','["Abre Eliminar este anuncio en Mis anuncios o dentro del editor.","Lee el aviso y escribe la confirmación solicitada antes de enviarlo.","Si solo quieres retirarlo temporalmente, utiliza Ocultar anuncio en su lugar.","Si ya lo eliminaste y necesitas recuperarlo, contacta al soporte; este asistente no restaura ni elimina datos."]','/mi-cuenta#mis-anuncios','Abrir mis anuncios',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('documents','account',NULL,'0','Privacidad','Carnet y examen médico privados','["carnet","identidad","documentos privados","certificado medico","examen medico"]','Estos documentos son opcionales para anuncios Escort y no aparecen en el perfil público.','["Desde Mis anuncios pulsa Documentos privados o abre esa sección del editor.","Adjunta cada documento por separado: JPG, PNG, WebP o PDF de hasta 15 MB.","Solo el dueño y administradores autorizados pueden consultar los archivos.","No adjuntes documentos ni datos médicos en el chat de ayuda; utiliza únicamente el formulario privado."]','/mi-cuenta#mis-anuncios','Abrir documentos privados','documents') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('stories','account',NULL,'0','Anuncios','Publicar historias, videos y estados de texto','["historia","estado de texto","historias de texto","subir historia","video de historia"]','Las historias pertenecen a cada anuncio publicado y duran 24 horas.','["En Mis anuncios pulsa Historias en el anuncio que esté publicado y visible.","Puedes escribir un estado de hasta 180 caracteres o elegir una foto original de hasta 20 MB; se prepara a un máximo final de 5 MB. HEIC depende del navegador.","Los videos se preparan igual que los del anuncio: máximo final 12 MB y 15 segundos, con marca de agua opcional. Solo se almacena el archivo final.","Se admiten hasta 5 textos, 5 fotos y 3 videos activos por anuncio. Vencen públicamente a las 24 horas; la limpieza programada elimina archivos y registros vencidos, normalmente dentro de los siguientes 5 minutos."]','/mi-cuenta#mis-anuncios','Abrir historias','stories') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('stats','account',NULL,'0','Anuncios','Estadísticas de mis anuncios','["estadisticas","visitas","visualizaciones","rendimiento","metricas"]','Tu panel resume actividad y rendimiento; cada anuncio tiene su sección de estadísticas.','["Revisa Tu actividad y Rendimiento de tus anuncios al inicio de Mi cuenta.","Para ver un anuncio concreto pulsa Estadísticas en Mis anuncios.","Los indicadores muestran el alcance registrado en Chile3X, no reservas ni pagos externos.","Una cuenta sin anuncios o sin actividad puede mostrar datos vacíos o en cero."]','/mi-cuenta#mis-anuncios','Abrir estadísticas','stats') ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('messages','account',NULL,'0','Mensajes y comentarios','Leer y enviar mensajes','["mensajes","chat","mensaje sin leer","notificacion mensaje","conversacion"]','El chat interno requiere una cuenta activa y cada conversación se vincula con un anuncio.','["Abre Mensajes desde tu panel o el aviso de mensajes sin leer.","Elige la conversación y escribe el mensaje; la fotografía del anuncio permite abrir su perfil.","Puedes silenciar avisos o bloquear mensajes nuevos en los controles de la conversación.","No envíes claves, códigos, documentos ni datos bancarios. Si la otra cuenta se deshabilita o elimina, se muestra Usuario de Chile3X y no se pueden enviar nuevos mensajes."]','/mi-cuenta/mensajes','Abrir mensajes',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('reviews','account',NULL,'0','Mensajes y comentarios','Mis comentarios y los que recibe mi anuncio','["comentario","resena","aprobar comentario","rechazar comentario","eliminar comentario"]','El anunciante aprueba o rechaza los comentarios recibidos. Un comentario propio pendiente es visible privadamente para su autor.','["Abre Favoritos y comentarios y elige Comentarios.","Revisa los enviados por ti y los recibidos en tus anuncios.","Como dueño puedes aprobar, rechazar o eliminar. Rechazar elimina el comentario; el autor puede retirar su propio comentario.","Administración puede consultar y eliminar comentarios, pero no aprobarlos ni rechazarlos por el anunciante."]','/mi-cuenta/comentarios','Abrir comentarios',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('favorites','account',NULL,'0','Mensajes y comentarios','Favoritos y anuncios ocultos','["favorito","me gusta","anuncios ocultos","desocultar","guardar anuncio"]','Favorito guarda un anuncio para ti. Ocultar un anuncio ajeno solo afecta a tu cuenta.','["En un anuncio público pulsa Favorito para guardarlo.","Tus favoritos están en Favoritos y comentarios → Favoritos.","Si ocultaste un anuncio ajeno, revisa Anuncios ocultos para volver a mostrarlo.","Me gusta es una reacción distinta de Favorito; ninguna de las dos inicia una conversación."]','/mi-cuenta/favoritos','Abrir favoritos',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('reports','account',NULL,'0','Privacidad','Reportar un anuncio y revisar mis reportes','["reportar","denunciar","reporte","fraude","suplantacion"]','Los reportes y sus evidencias se consultan privadamente desde tu cuenta.','["En el anuncio utiliza Reportar anuncio e indica el motivo.","Describe lo que ocurrió y adjunta evidencias dentro de los límites del formulario.","En Mis reportes puedes consultar el estado y los archivos que enviaste.","Para una urgencia o si el formulario no funciona, contacta al equipo; el chat de ayuda no presenta reportes automáticamente."]','/mi-cuenta/reportes','Abrir mis reportes',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('identity','account',NULL,'0','Cuenta y acceso','Cambiar nombre, usuario y datos de la cuenta','["nombre de usuario","cambiar usuario","correo","email","mis datos","nombre de cuenta"]','Los datos de tu cuenta y el @ de cada anuncio se administran por separado.','["Abre Mis datos para editar los datos que permita el formulario.","Tu nombre de usuario debe ser único y no puede coincidir con el @ de un anuncio.","El correo de tu cuenta aparece en el acceso superior; no es necesariamente el contacto público del anuncio.","Para cambiar el @ o contacto del anuncio, utiliza Editar anuncio."]','/mi-cuenta/datos-personales','Abrir mis datos',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('password','account',NULL,'0','Cuenta y acceso','Crear, cambiar o recuperar contraseña','["contrasena","clave","password","recuperar acceso","olvide mi clave"]','Dentro de tu cuenta puedes crear o cambiar tu contraseña; si no puedes entrar, utiliza recuperación.','["En Mis datos abre Crear contraseña o Cambiar contraseña.","Completa y confirma la nueva clave en el formulario seguro, nunca en este chat.","Si no puedes iniciar sesión, utiliza Olvidé mi clave y revisa también Spam.","El enlace de recuperación es temporal y de un solo uso. El asistente no conoce ni puede mostrar tus claves."]','/mi-cuenta/datos-personales#password','Abrir contraseña',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('email-verification','account',NULL,'0','Cuenta y acceso','Verificar mi correo','["verificar correo","correo no verificado","reenviar verificacion","confirmar email"]','Cuando falte verificar tu correo, el panel muestra el aviso y su plazo.','["Busca el aviso de verificación al inicio del panel.","Solicita un nuevo enlace si el anterior caducó y revisa Spam.","Abre el enlace del correo de Chile3X; no compartas sus códigos ni enlaces privados en el chat.","Si registraste la cuenta con Google, el correo puede haber quedado verificado durante ese acceso."]','/mi-cuenta','Revisar verificación',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('social','account',NULL,'0','Cuenta y acceso','Desvincular Google, Apple o X','["desvincular google","desvincular apple","desvincular x","cuentas conectadas","twitter"]','Desvincular quita ese método de acceso, sin desverificar automáticamente el correo de tu cuenta.','["Abre Mis datos y la sección de accesos conectados.","Si no tienes una contraseña, créala antes de desvincular el proveedor.","Lee y confirma la desvinculación para mantener una forma de volver a entrar.","Apple y X solo se pueden utilizar cuando administración los haya configurado y activado; un botón deshabilitado no inicia sesión."]','/mi-cuenta/datos-personales','Abrir accesos conectados',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('account-close','account',NULL,'0','Privacidad','Deshabilitar o eliminar mi cuenta','["eliminar cuenta","borrar cuenta","deshabilitar cuenta","cerrar cuenta"]','Deshabilitar es reversible. Eliminar la cuenta es permanente y no recupera sus datos al registrarte nuevamente.','["Abre Mis datos → Deshabilitar o eliminar.","Lee cuidadosamente las consecuencias y la confirmación que pide el formulario.","Deshabilitar cierra sesiones y oculta anuncios; eliminar borra la cuenta y sus datos asociados.","El asistente no ejecuta ninguna de estas acciones ni solicita tu contraseña."]','/mi-cuenta/datos-personales','Abrir opciones de cuenta',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('exclusive','account',NULL,'0','Contenido y comunidad','Contenido exclusivo y accesos','["contenido exclusivo","desbloquear contenido","contenido privado","autorizar acceso","mi contenido"]','El contenido exclusivo pertenece a la cuenta anunciante y solo está disponible para cuentas autorizadas.','["Abre Mi contenido. Como comprador revisa Mi contenido desbloqueado.","Como anunciante administra tu biblioteca, carga sus archivos y espera la revisión de cada medio.","Autoriza o retira el acceso de cuentas desde los controles de la biblioteca.","Chile3X no procesa pagos ni garantiza acuerdos externos. Un anuncio pausado no elimina automáticamente los accesos de la biblioteca."]','/mi-cuenta/contenido','Abrir mi contenido',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('telegram','account',NULL,'0','Contenido y comunidad','Vincular Telegram y acceder a Miembros','["telegram","miembros","vincular telegram","invitacion"]','La comunidad pública y el acceso privado de Miembros son espacios distintos.','["Abre Telegram desde tu cuenta.","Con una cuenta activa y correo verificado, sigue los pasos para vincular tu identidad con el bot.","Solicita la invitación temporal al espacio privado cuando corresponda.","No compartas códigos de vinculación. Si una invitación vence, solicita otra desde el panel."]','/mi-cuenta/telegram','Abrir Telegram',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('tester','account',NULL,'1','Pruebas','Enviar un error de QA','["qa","tester","reportar bug","mis pruebas"]','Las cuentas tester tienen un panel de pruebas y reportes de errores.','["Abre Mis pruebas.","Describe los pasos, el resultado esperado y lo que pasó realmente.","Adjunta evidencia sin incluir documentos, contraseñas ni información de otras cuentas.","Consulta ahí las respuestas y el estado de seguimiento del equipo."]','/mi-cuenta/pruebas','Abrir mis pruebas',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-edit','admin','profiles.moderate','0','Anuncios','Editar un anuncio de otra cuenta','["editar anuncio","cambiar foto","modificar anuncio","datos del anuncio"]','Desde Anuncios y publicaciones puedes abrir el editor completo de cada anuncio.','["Busca el anuncio y pulsa Editar anuncio.","Utiliza los accesos a Editar datos, Fotos y videos, Documentos privados e Historias y estados.","Guardar datos conserva el estado administrativo: no publica un anuncio pendiente ni retira uno aprobado.","Las acciones administrativas quedan en Actividad. Los archivos privados y las cargas requieren sus permisos específicos."]','/admin/anuncios-publicaciones','Buscar anuncio para editar',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-status','admin','profiles.moderate','0','Anuncios','Aprobar, rechazar o cambiar estados de un anuncio','["aprobar anuncio","rechazar anuncio","publicacion","guardar estados","verificacion","revision medica"]','Publicación, verificación y revisión médica son controles diferentes.','["En Anuncios y publicaciones filtra por estado o busca nombre, usuario o cuenta.","Revisa el anuncio y sus archivos antes de decidir.","Elige los estados correspondientes y pulsa Guardar estados.","No se puede publicar una cuenta deshabilitada. El historial registra quién cambió los estados."]','/admin/anuncios-publicaciones','Abrir moderación de anuncios',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-media','admin','media.moderate','0','Fotos y videos','Revisar y aprobar fotos, videos o contenido exclusivo','["aprobar fotos","aprobar todos","aceptar fotos","videos pendientes","contenido exclusivo pendiente","rechazar foto"]','La moderación de medios es independiente del estado del anuncio.','["Abre Medios o Revisar medios desde el anuncio.","Separa galería pública, foto principal y contenido exclusivo; revisa cada archivo.","Puedes aprobar un archivo o usar la aprobación conjunta cuando hayas revisado los pendientes del grupo.","El historial registra la acción. Aprobar contenido exclusivo no lo vuelve público ni autoriza cuentas por sí solo."]','/admin/medios','Abrir medios',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-documents','admin','private.view','0','Privacidad','Consultar carnet y examen médico privados','["carnet","examen medico","documentos privados","identidad"]','El acceso a documentos privados requiere permiso específico y queda registrado.','["Desde Anuncios y publicaciones pulsa Documentos privados en un anuncio Escort.","Abre el archivo de identidad o médico desde la sección privada del editor.","No publiques ni copies estos archivos a conversaciones de ayuda.","Si no aparece el acceso, revisa tus permisos con el propietario; el asistente no puede ampliarlos."]','/admin/anuncios-publicaciones','Buscar documentos del anuncio',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-stories','admin','profiles.moderate','0','Anuncios','Publicar historias y estados para un anunciante','["historia","estado de texto","publicar texto","subir historia","video de historia"]','Administración puede publicar historias en nombre de una cuenta desde el editor del anuncio.','["Abre Editar anuncio → Historias y estados.","El anuncio debe estar publicado, visible y pertenecer a una cuenta activa.","Texto de hasta 180 caracteres, foto final de hasta 5 MB o video preparado de hasta 12 MB y 15 segundos. Fotos y videos requieren permiso de medios.","Hasta 5 textos, 5 fotos y 3 videos activos, con duración de 24 horas y limpieza automática posterior. Publicar o eliminar registra tu identidad administrativa, sin duplicar el archivo ni conservar su contenido en la auditoría."]','/admin/anuncios-publicaciones','Elegir anuncio para historias',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-reviews','admin','reviews.moderate','0','Mensajes y comentarios','Consultar o eliminar comentarios','["comentario","resena","aprobar comentario","rechazar comentario","eliminar comentario"]','Solo el anunciante aprueba o rechaza; administración puede consultar y eliminar.','["En un anuncio utiliza Comentarios o abre Reseñas del panel.","Revisa los comentarios pendientes o publicados y la cuenta autora.","Si corresponde, utiliza Eliminar comentario.","No hay aprobación o rechazo administrativo. Los rechazados por el anunciante se eliminan."]','/admin/resenas','Abrir comentarios administrativos',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-accounts','admin','accounts.manage','0','Cuenta y acceso','Administrar cuentas o crearles un anuncio','["cuentas","crear cuenta","crear anuncio para usuario","deshabilitar cuenta","datos de usuario"]','Cuentas reúne la gestión de cada usuario y la creación asistida de anuncios.','["Busca y abre la cuenta en Cuentas.","Revisa datos, anuncios y acciones permitidas para tu acceso.","Utiliza Crear anuncio para esa cuenta; después carga sus medios y publícalo desde moderación.","Lee las confirmaciones antes de deshabilitar o eliminar. Las acciones quedan registradas."]','/admin/cuentas','Abrir cuentas',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-audit','admin','audit.view','0','Administración','Historial y últimos movimientos','["historial","actividad","quien aprobo","ultimos movimientos","auditoria","whatsapp clics"]','El resumen muestra los últimos 10 movimientos; Actividad permite revisar el historial y sus filtros.','["En Resumen revisa Últimos 10 movimientos.","En Actividad filtra por administrador, área, acción, fechas o entidad.","Abre los detalles para revisar quién actuó y los cambios registrados.","Las métricas de contacto reflejan clics registrados, no mensajes enviados ni acuerdos concretados."]','/admin/actividad','Abrir actividad administrativa',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-reports','admin','reports.manage','0','Privacidad','Atender reportes de usuarios','["reporte","denuncia","fraude","evidencia"]','Reportes reúne los casos enviados por usuarios y su seguimiento.','["Abre Reportes y selecciona el caso.","Revisa motivo, anuncio y evidencias según tus permisos.","Actualiza el estado y deja el seguimiento que permita el formulario.","Mantén las evidencias privadas y no pegues datos sensibles en la ayuda."]','/admin/reportes','Abrir reportes',NULL) ON CONFLICT(id) DO NOTHING;

