INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-config','admin','settings.manage','0','Administración','Configuración, SEO, accesos y soporte','["configuracion","seo","google","apple","twitter","x","whatsapp","contacto","reglas","faq"]','Configuración separa operación, SEO, proveedores de acceso, contactos, FAQ y medios.','["Abre Configuración y elige la categoría correspondiente.","Cambia solo los campos de ese apartado y guarda.","No pegues claves, secretos o credenciales en el chat. Apple y X no se activan solo por mostrar un botón.","Los WhatsApp que ofrece esta ayuda proceden de Contacto y redes, no de una lista independiente."]','/admin/configuracion','Abrir configuración',NULL) ON CONFLICT(id) DO NOTHING;

