INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-telegram','admin','telegram.view','0','Contenido y comunidad','Comunidad de Telegram','["telegram","miembros","bot","comunidad"]','El panel muestra la comunidad; cada acción depende de los permisos de publicación, moderación o configuración.','["Abre Telegram.","Revisa el estado del bot, los chats y las alertas disponibles para tu función.","Publica o modera únicamente desde los controles habilitados.","No compartas tokens ni enlaces privados de invitación en este chat."]','/admin/telegram','Abrir Telegram administrativo',NULL) ON CONFLICT(id) DO NOTHING;

