INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-news','admin','news.manage','0','Contenido y comunidad','Publicar noticias y novedades','["noticia","novedad","publicar articulo"]','Noticias permite gestionar el contenido editorial del sitio.','["Abre Noticias y crea o edita la publicación.","Revisa título, contenido, imágenes y estado antes de publicar.","Comprueba el resultado público y los datos SEO del artículo.","La sincronización con Telegram depende de su configuración y tus permisos."]','/admin/noticias','Abrir noticias',NULL) ON CONFLICT(id) DO NOTHING;

