INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-sponsors','admin','settings.manage','0','Administración','Administrar sitios asociados','["patrocinador","sitios asociados","banner","sexshop"]','Sitios asociados agrupa las referencias y materiales visibles de colaboradores.','["Abre Sitios asociados.","Configura el grupo, los datos y sus imágenes.","Revisa la visibilidad y los enlaces antes de guardar.","Comprueba el resultado sin prometer acuerdos o servicios que no estén confirmados."]','/admin/patrocinadores','Abrir sitios asociados',NULL) ON CONFLICT(id) DO NOTHING;

