INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-access','admin','admins.manage','0','Cuenta y acceso','Permisos de administradores','["administrador","permiso","moderador","autorizar admin","rol"]','Solo el propietario protegido puede gestionar los accesos administrativos.','["Abre Administradores.","Revisa el acceso y la función de la persona antes de cambiarlo.","Asigna únicamente los permisos que necesite.","Los cambios se registran. Este asistente no concede permisos ni pide credenciales."]','/admin/administradores','Abrir administradores',NULL) ON CONFLICT(id) DO NOTHING;

