INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-trash','admin','profiles.recycle','0','Anuncios','Restaurar un anuncio de la papelera','["papelera","restaurar anuncio","recuperar anuncio eliminado","eliminar definitivamente"]','Restaurar y eliminar definitivamente son acciones distintas; la segunda no se puede deshacer.','["En Anuncios y publicaciones abre Ver papelera.","Encuentra el anuncio y revisa su propietario y estado.","Utiliza Restaurar si deseas recuperarlo y comprueba después su estado de publicación.","La eliminación definitiva exige su confirmación específica. La ayuda no ejecuta esta acción."]','/admin/anuncios-publicaciones/papelera','Abrir papelera',NULL) ON CONFLICT(id) DO NOTHING;

