INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('general-location','all',NULL,'0','Directorio','Ubicación, filtros y ciudades','["ciudad","region","ubicacion","filtro","mapa"]','La ubicación del anuncio es independiente de la ubicación administrativa de la cuenta.','["En el directorio elige una ciudad o vuelve a Todo Chile.","Combina los filtros disponibles para encontrar anuncios.","La ubicación pública y el mapa son referenciales de la ciudad, no una dirección exacta.","Para cambiar la ciudad de un anuncio, utiliza su editor; cambiar Mis datos no lo traslada."]','/escorts','Abrir directorio',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('general-gallery','all',NULL,'0','Directorio','Ver fotos grandes y cambiar las columnas','["galeria","columnas","foto grande","cerrar fotografia","videos"]','Las fotos y videos tienen galerías separadas y opciones de distribución según la cantidad disponible.','["Abre el anuncio y usa los iconos de distribución en su galería.","Pulsa una fotografía para verla ampliada sin abrir otra pestaña.","Cierra con la X para continuar donde estabas.","Los videos aparecen debajo de las fotos y sus miniaturas no inician la reproducción automáticamente."]','/escorts','Explorar anuncios',NULL) ON CONFLICT(id) DO NOTHING;

