INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-forum','admin','forum.manage','0','Foro privado','Administrar el foro beta','["foro","seccion foro","tema","cerrar tema","fijar tema","respuesta foro"]','El foro beta solo admite administradores habilitados. No está abierto a usuarios ni buscadores.','["Abre Foro desde el panel administrativo.","En Administrar secciones puedes crear grupos, nombres, descripciones, reglas y orden. Archivar conserva sus temas.","Crea un tema y prueba respuestas. En Administrar este tema puedes fijarlo, cerrarlo, moverlo o enviarlo a papelera.","Desmarcar Papelera recupera el contenido. No incluyas documentos privados ni datos de anunciantes; los cambios quedan en Actividad."]','/foro','Abrir foro privado beta',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('admin-help-toggle','admin','settings.manage','0','Administración','Activar o desactivar el bot de ayuda','["desactivar ayuda","ocultar johnny","activar bot","ayuda beta","interruptor ayuda"]','Configuración → Bot de ayuda beta controla la navegación y la URL de ayuda de las cuentas.','["Abre Configuración → Bot de ayuda beta.","Selecciona Visible y disponible o Desactivado para usuarios y guarda.","Desactivar oculta el enlace y bloquea /mi-cuenta/ayuda en nuevas cargas; una pestaña ya abierta conserva las guías hasta recargarla.","La ayuda administrativa permanece disponible y el cambio queda registrado. No activa servicios de IA ni gastos."]','/admin/configuracion/ayuda','Configurar bot de ayuda',NULL) ON CONFLICT(id) DO NOTHING;

--> statement-breakpoint
INSERT INTO help_guides(id,audience,capability,tester_only,category,title,aliases,summary,steps,link_href,link_label,link_target) VALUES ('general-help','all',NULL,'0','Ayuda','Qué puede hacer Johnny Sins','["ayuda","hola","johnny","que puedes hacer","soporte","hablar con humano"]','Soy el bot de ayuda beta de Chile3X: un chat-buscador de guías revisadas, sin IA generativa ni acciones automáticas.','["Pregunta por una tarea o busca palabras como cambiar foto, mensajes o historias.","Puedes abrir una guía, seguir sus pasos y navegar a la sección indicada.","Puedo equivocarme o no cubrir tu caso. No accedo a tus contraseñas, documentos ni conversaciones.","Si no se soluciona, utiliza los WhatsApp oficiales de soporte que aparecen aquí."]','/contacto','Abrir contacto oficial',NULL) ON CONFLICT(id) DO NOTHING;
